import { createContext, useState } from "react";

export const ContexteAuth = createContext();

export function AuthProvider({ children }) {
  const [utilisateur, setUtilisateur] = useState(
    () => JSON.parse(localStorage.getItem("utilisateur")) || null
  );

  // ✅ LOGIN
  const login = ({ email, motDePasse }) => {
    // simulation (tu peux remplacer par API)
    const user = {
      nom: "Utilisateur",
      email: email,
    };

    setUtilisateur(user);
    localStorage.setItem("utilisateur", JSON.stringify(user));
  };
  

  // ✅ LOGOUT
  const logout = () => {
    setUtilisateur(null);
    localStorage.removeItem("utilisateur");
  };

  return (
    <ContexteAuth.Provider value={{ utilisateur, login, logout }}>
      {children}
    </ContexteAuth.Provider>
  );
}
